size_t heap_map(char *out, size_t cap) {
    size_t n = 0;
    for (Block *b = first_block(); b; b = next_block(b)) {
        if (cap && n < cap - 1) out[n] = {{0}};
        n++;
        for (size_t i = 0; i < b->size / {{1}}; i++) {
            if (cap && n < cap - 1) out[n] = b->is_free ? {{2}} : {{3}};
            n++;
        }
    }
    if (cap) out[n < cap ? n : cap - 1] = 0;
    return n;
}
